import{_ as t,o as a,c as s,a2 as i}from"./chunks/framework.CyZTVJbV.js";const k=JSON.parse('{"title":"Stack five test layers on a single feature","description":"","frontmatter":{},"headers":[],"relativePath":"en/cookbook/five-layer-stack.md","filePath":"en/cookbook/five-layer-stack.md"}'),l={name:"en/cookbook/five-layer-stack.md"};function o(n,e,d,r,c,h){return a(),s("div",null,[...e[0]||(e[0]=[i(`<h1 id="stack-five-test-layers-on-a-single-feature" tabindex="-1">Stack five test layers on a single feature <a class="header-anchor" href="#stack-five-test-layers-on-a-single-feature" aria-label="Permalink to &quot;Stack five test layers on a single feature&quot;">​</a></h1><blockquote><p><a href="./five-layer-stack">🇬🇧 English</a> • <a href="./../../ja/cookbook/five-layer-stack">🇯🇵 日本語</a></p></blockquote><p><a href="./three-layer-stack">Stack three layers on the same contract</a> shows how Foundry / Hardhat / Playwright run side by side on one Solidity contract. With the F-3 skills (<code>/kiwa-vitest</code> and <code>/kiwa-api</code>) you can now stack five layers on the same feature when the feature also has TS / TSX logic and an HTTP / RPC adapter.</p><h2 id="the-five-layers" tabindex="-1">The five layers <a class="header-anchor" href="#the-five-layers" aria-label="Permalink to &quot;The five layers&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Layer</th><th>Skill</th><th>What it tests</th><th>Output path</th></tr></thead><tbody><tr><td>Contract (Foundry)</td><td><code>/kiwa-forge</code></td><td>Solidity <code>*.sol</code> against <code>forge test</code></td><td><code>test/{Contract}.t.sol</code></td></tr><tr><td>Contract (Hardhat)</td><td><code>/kiwa-hardhat</code></td><td>Same Solidity contract via <code>solidity-coverage</code></td><td><code>hardhat-test/{Contract}.test.cjs</code></td></tr><tr><td>Unit (Vitest)</td><td><code>/kiwa-vitest</code></td><td>TS helpers / TSX hooks under <code>src/lib/</code> / <code>hooks/</code></td><td><code>test/unit/{module}.test.{ts,tsx}</code></td></tr><tr><td>Integration (API)</td><td><code>/kiwa-api</code></td><td>HTTP / RPC handlers under <code>app/api/*/route.ts</code> via msw / supertest / Playwright <code>request</code></td><td><code>test/integration/{module}.test.ts</code></td></tr><tr><td>E2E (Playwright)</td><td><code>/kiwa-play</code></td><td>dApp flow with <code>@kiwa-test/dapp</code> fixture (browser + anvil)</td><td><code>tests/{module}.spec.ts</code></td></tr></tbody></table><h2 id="when-five-layers-pay-off" tabindex="-1">When five layers pay off <a class="header-anchor" href="#when-five-layers-pay-off" aria-label="Permalink to &quot;When five layers pay off&quot;">​</a></h2><p>The five-layer stack is overkill for a contract-only feature (e.g. ERC-721 mint with a static metadata URL — the three-layer stack covers it). It pays off when the feature has all three of the following.</p><ul><li>A Solidity surface that needs both Foundry and Hardhat (e.g. invariant on Foundry, coverage on Hardhat)</li><li>TS / TSX helpers that compute fees / build calldata / format addresses outside React</li><li>An HTTP / RPC adapter that the frontend calls and that talks to the contract</li></ul><p>Concrete examples — <code>mint-nft</code> with a fee-calculation hook and an <code>/api/mint</code> endpoint, <code>defi-swap</code> with a slippage calculator and an <code>/api/quote</code> endpoint, <code>nextjs-token-gating</code> with a metadata fetcher and a <code>/api/access</code> endpoint.</p><h2 id="how-the-five-layers-stay-aligned" tabindex="-1">How the five layers stay aligned <a class="header-anchor" href="#how-the-five-layers-stay-aligned" aria-label="Permalink to &quot;How the five layers stay aligned&quot;">​</a></h2><p>The Layer 1 spec is still the single source of truth. <code>/kiwa-design --layer all</code> (or each <code>--layer contract</code> / <code>--layer e2e</code> / <code>--layer unit</code> / <code>--layer integration</code> in sequence) writes a spec under <code>tests/spec/{layer}/test-spec-{module}.md</code> and every Layer 2 skill reads it.</p><div class="language-mermaid vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">mermaid</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">graph LR</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    A[Feature] --&gt; B[/kiwa-design]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    B --&gt; C1[contract spec]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    B --&gt; C2[e2e spec]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    B --&gt; C3[unit spec]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    B --&gt; C4[integration spec]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    C1 --&gt; D1[/kiwa-forge]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    C1 --&gt; D2[/kiwa-hardhat]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    C3 --&gt; D3[/kiwa-vitest]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    C4 --&gt; D4[/kiwa-api]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    C2 --&gt; D5[/kiwa-play]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    D1 --&gt; E1[forge test]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    D2 --&gt; E2[hardhat test]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    D3 --&gt; E3[vitest run]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    D4 --&gt; E4[vitest run integration]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    D5 --&gt; E5[playwright test]</span></span></code></pre></div><h2 id="how-to-add-a-fifth-layer-to-an-existing-example" tabindex="-1">How to add a fifth layer to an existing example <a class="header-anchor" href="#how-to-add-a-fifth-layer-to-an-existing-example" aria-label="Permalink to &quot;How to add a fifth layer to an existing example&quot;">​</a></h2><p>Pick an example that already has the three-layer stack (mint-nft / defi-swap / nextjs-token-gating). Add the missing unit + integration layers in the following order.</p><ol><li><code>/kiwa-design --layer unit --module &lt;name&gt; --input src/lib/&lt;helper&gt;.ts</code></li><li><code>/kiwa-vitest --module &lt;name&gt;</code> → <code>test/unit/&lt;name&gt;.test.ts</code></li><li><code>/kiwa-design --layer integration --module &lt;name&gt; --input app/api/&lt;route&gt;/route.ts</code></li><li><code>/kiwa-api --module &lt;name&gt; --backend msw</code> (or <code>supertest</code> for Express-style)</li></ol><p>After both Layer 2 skills converge to their coverage targets, the feature has five independent regression nets that catch different failure modes:</p><ul><li>Foundry catches Solidity invariants under fuzz</li><li>Hardhat catches Solidity coverage gaps via <code>solidity-coverage</code></li><li>Vitest catches TS helper / TSX hook regressions</li><li>msw / supertest catches HTTP boundary bugs (validation, status codes, idempotency)</li><li>Playwright catches the end-to-end UX path</li></ul><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="./three-layer-stack"><code>three-layer-stack.md</code></a> — Contract-only three-layer stack</li><li><a href="./../../../tests/docs/skill-chain-tutorial"><code>tests/docs/skill-chain-tutorial.md</code></a> — Full skill-chain flow</li><li><a href="./../../../.claude/skills/kiwa-vitest/SKILL"><code>.claude/skills/kiwa-vitest/SKILL.md</code></a> — Unit layer skill spec</li><li><a href="./../../../.claude/skills/kiwa-api/SKILL"><code>.claude/skills/kiwa-api/SKILL.md</code></a> — Integration layer skill spec</li></ul>`,19)])])}const y=t(l,[["render",o]]);export{k as __pageData,y as default};
